(1,	'Home',	'<h2>40% OFF&nbsp;</h2><p>Ace your exam with our expertly curated selection of competitve exam books. To get all RAS class and books -</p>',	'Shop Now',	'#',	'home-page/banner/01JSEG0QKNZR6DJBMJ6A948CQE.png',	'\"home-page\\/banner\\/01JSGPD3B1FFDX73HRJA0CGAYP.png\"',	'Top Book Categories',	'Explore our diverse range of categories and embark on a reading journey that suits your mood, passion, or curiosity.',	'[{\"cat_title\":\"Bestselling Books\",\"cat_image\":\"home-page\\/catgegory\\/01JSE5PCTS6WX44GQBCZ97J6SE.jpeg\",\"cat_content\":\"Explore our extensive collection of textbooks, workbooks, novels, and more. From preschool to post-grad, we have books for every age and academic level.\\n\",\"cat_button_title\":\"Shop Now\",\"cat_button_url\":\"school-books\",\"cat_icon\":null},{\"cat_title\":\"Fiction Books\",\"cat_image\":\"home-page\\/catgegory\\/01JSE5WBR35E5KZNHYD2EKN1YJ.jpeg\",\"cat_content\":\"up to 40% OFF\\n\",\"cat_button_title\":null,\"cat_button_url\":null,\"cat_icon\":\"home-page\\/catgegory\\/01JSEJKKX38ZD2N4MVCRBYTBWR.svg\"},{\"cat_icon\":\"home-page\\/catgegory\\/01JSGMG2HY3FMS4YB12WCYX2Z6.svg\",\"cat_title\":\"GK Books \",\"cat_image\":\"home-page\\/catgegory\\/01JSGMG2J1K1F8W91AHXSSA5KA.jpg\",\"cat_content\":\"<p>up to 10% OFF&nbsp;<\\/p>\",\"cat_button_title\":null,\"cat_button_url\":null},{\"cat_icon\":\"home-page\\/catgegory\\/01JSGMK6AVAJEMNBDB20Y7C5CB.svg\",\"cat_title\":\"RRB\",\"cat_image\":\"home-page\\/catgegory\\/01JSGMK6AYHY5QVVC62QT3HF7H.jpeg\",\"cat_content\":\"<p>up to 10% OFF&nbsp;<\\/p>\",\"cat_button_title\":null,\"cat_button_url\":null},{\"cat_icon\":\"home-page\\/catgegory\\/01JSGNG2R06Z6Y324ZF2RH4M53.png\",\"cat_title\":\"Test Books\",\"cat_image\":\"home-page\\/catgegory\\/01JSGNG2R5S8M4YPMA403VP958.webp\",\"cat_content\":\"<p>up to 50%&nbsp;<\\/p>\",\"cat_button_title\":null,\"cat_button_url\":null}]',	'up to 40% OFF',	'Back to the Books',	'We offer a wide range of study guides, test prep materials, and reference books. Whether you\'re tackling calculus or diving into Shakespeare, we\'ve got you covered.',	'[\"113\",\"69\",\"70\",\"76\"]',	'[{\"testimonial_content\":\"Ace your exam with our expertly curated selection of competitve exam books.To get all RAS class and books\",\"testimonial_image\":\"home-page\\/testimonial\\/01JSEC2DC8QEE6XC9GVAGEDTDH.png\",\"testimonial_button_title\":\"Buy Now\",\"testimonial_button_url\":\"#\"},{\"testimonial_content\":\"Ace your exam with our expertly curated selection of competitve exam books.To get all RAS class and book\",\"testimonial_image\":\"home-page\\/testimonial\\/01JSEC2DCBPT0ZXM5Q0VRC068R.png\",\"testimonial_button_title\":\"Buy Now\",\"testimonial_button_url\":\"#\"}]',	'Feature Products',	'[]',	NULL,	NULL,	NULL,	NULL,	'Get your book from us!',	'Start your literary adventure today by exploring these captivating worlds of words.',	'[{\"title\":\"We Support Educators\",\"image\":\"home-page\\/sections\\/01JSECHAMAMP5J53KRFDHXNP6F.svg\",\"content\":\"<p>Explore our educator resources, bulk ordering options, and special teacher discounts.<\\/p>\"},{\"title\":\"Support 24\\/7\",\"image\":\"home-page\\/sections\\/01JSECKZNVFFD708R47B5HK17J.svg\",\"content\":\"<p>Our dedicated customer support team is available to assist you 24 hours a day, 7 days a week.<\\/p>\"},{\"title\":\"Easy Shopping, Quick Delivery\",\"image\":\"home-page\\/sections\\/01JSECXGJ74WFJZK6EQZN7HKGR.svg\",\"content\":\"<p>We offer fast and reliable shipping, so you can focus on what matters most - your education<\\/p>\"}]',	'2025-04-22 00:17:09',	'2025-05-06 06:52:39');
