INSERT INTO `news` (`id`, `title`, `slug`, `news_category_id`, `content`, `feature_image`, `created_at`, `updated_at`) VALUES
(5,	'Delhi exit polls: Lotus set to bloom again in capital as pollsters predict big BJP win. What about Kejriwal AAP',	'delhi-exit-polls-lotus-set-to-bloom-again-in-capital-as-pollsters-predict-big-bjp-win-what-about-kejriwal-aap',	2,	'<p>The results of the Delhi assembly election 2025 will declared on Saturday but predictions are still pouring in before the big day. Most exit polls have predicted a big victory for the Bharatiya Janata Party (BJP) in the national capital.</p>',	NULL,	'2025-04-23 07:29:07',	'2025-04-23 07:29:07'),
(6,	'RBI Introduces Additional Factor Authentication for International Transactions',	'rbi-introduces-additional-factor-authentication-for-international-transactions',	2,	'<p>The<a href=\"https://www.gktoday.in/reserve-bank-of-india-digital-payments-index/\"> </a>RBI has announced enhancement to the security of online payments. This new measure focuses on cross-border “Card Not Present” (CNP) transactions. The introduction of Additional Factor of <a href=\"https://www.gktoday.in/rbi-introduces-additional-factor-authentication-for-international-transactions/#\">&nbsp;</a>AFA aims to ensure that international digital transactions using Indian-issued cards are as secure as domestic ones. This move comes in response to the increasing volume of online shopping and the associated rise in fraud risks.</p>',	NULL,	'2025-04-23 07:29:21',	'2025-04-23 07:29:21'),
(7,	'इंडिया ने तूफानी अंदाज में जीता पहला वनडे, इंग्लैंड को बुरी तरह धोया',	'इंडिया-ने-तूफानी-अंदाज-में-जीता-पहला-वनडे',	1,	'<p><a href=\"http://localhost:3000/current-affairs/%E0%A4%87%E0%A4%82%E0%A4%A1%E0%A4%BF%E0%A4%AF%E0%A4%BE-%E0%A4%A8%E0%A5%87-%E0%A4%A4%E0%A5%82%E0%A4%AB%E0%A4%BE%E0%A4%A8%E0%A5%80-%E0%A4%85%E0%A4%82%E0%A4%A6%E0%A4%BE%E0%A4%9C-%E0%A4%AE%E0%A5%87%E0%A4%82-%E0%A4%9C%E0%A5%80%E0%A4%A4%E0%A4%BE-%E0%A4%AA%E0%A4%B9%E0%A4%B2%E0%A4%BE-%E0%A4%B5%E0%A4%A8%E0%A4%A1%E0%A5%87,-%E0%A4%87%E0%A4%82%E0%A4%97%E0%A5%8D%E0%A4%B2%E0%A5%88%E0%A4%82%E0%A4%A1-%E0%A4%95%E0%A5%8B-%E0%A4%AC%E0%A5%81%E0%A4%B0%E0%A5%80-%E0%A4%A4%E0%A4%B0%E0%A4%B9-%E0%A4%A7%E0%A5%8B%E0%A4%AF%E0%A4%BE\"><strong>इंडिया ने तूफानी अंदाज में जीता पहला वनडे, इंग्लैंड को बुरी तरह धोया<br></strong></a><br></p>',	NULL,	'2025-04-24 00:19:07',	'2025-04-24 00:58:08'),
(8,	'राष्ट्रीय नमूना सर्वेक्षण (एनएसएस) की 75वीं वर्षगांठ',	'राष्ट्रीय-नमूना-सर्वेक्षण-(एनएसएस)-की-75वीं-वर्षगांठ',	1,	'<p><a href=\"http://localhost:3000/current-affairs/%E0%A4%B0%E0%A4%BE%E0%A4%B7%E0%A5%8D%E0%A4%9F%E0%A5%8D%E0%A4%B0%E0%A5%80%E0%A4%AF-%E0%A4%A8%E0%A4%AE%E0%A5%82%E0%A4%A8%E0%A4%BE-%E0%A4%B8%E0%A4%B0%E0%A5%8D%E0%A4%B5%E0%A5%87%E0%A4%95%E0%A5%8D%E0%A4%B7%E0%A4%A3-(%E0%A4%8F%E0%A4%A8%E0%A4%8F%E0%A4%B8%E0%A4%8F%E0%A4%B8)-%E0%A4%95%E0%A5%80-75%E0%A4%B5%E0%A5%80%E0%A4%82-%E0%A4%B5%E0%A4%B0%E0%A5%8D%E0%A4%B7%E0%A4%97%E0%A4%BE%E0%A4%82%E0%A4%A0\"><strong>राष्ट्रीय नमूना सर्वेक्षण (एनएसएस) की 75वीं वर्षगांठ</strong></a></p>',	NULL,	'2025-04-24 00:57:52',	'2025-04-24 00:57:52');
